-- ============================================================================
-- FC9: Corrosion & Integrity joins the catalog, the NINTH Facilities course.
--
-- Catalog row (module 'facilities'; path_order 47, directly above FC8 at 46,
-- FC7 at 45, FC6 heattransfer at 44, FC5 at 43, FC4 gasprocessing at 42, FC3
-- rotating at 41, FC2 linesizing at 40 and FC1 separation at 39; prereq_slug
-- NULL, the carried-over answer "no hard prerequisite inside a module") plus
-- the three capstones and their eighteen graded fields, generated by
-- tools/course-waves/corrosion/gen_course.py from fields.json, precision.json
-- and the capstone conditions in fc9_capstone.mjs. Deep seeds are three
-- separate migrations; the go-live is a fifth and is HELD until a NextGen
-- production upload carries the route /dashboard/apps/corrosion, because the
-- 78 lessons, the teaching lab (corrosionLab.js) and its three explorer panels
-- ship in the zip and not in this database.
--
-- THE ONE SENTENCE THE COURSE IS. This engine is a CO2 corrosion rate screen
-- with a remaining-life division on the end of it, most of its numbers have no
-- source, and the discipline is grading only what it can stand behind.
--
-- THE ENGINE. engines/facilities/corrosion.js, vendored sha-identical with
-- engines d4c19ad (the FC9-0 repair and the WITHDRAWAL of the invented
-- sour-service severity region). It imports nothing. `regionProvided` and
-- `materialGuidanceProvided` come back false on every screening.
--
-- NOTHING GRADED IS A CORROSION RATE THE CORRELATION PRODUCED, and each held
-- item is cleared by CONSTRUCTION, IDENTITY, CANCELLATION or EXCLUSION, each
-- one measured in fc9_capstone.mjs rather than asserted. OBIGBO grades the
-- partial pressures, a mole ratio, this module's Reynolds number (a definition,
-- upstream of the held Blasius pair) and the corrosion inhibitor arithmetic;
-- NEMBE CREEK and SOKU state their uninhibited rate from an inspection survey,
-- so no de Waard-Milliams constant, no scale factor and no pH correction is in
-- any graded chain, and every capstone sits below its own computed film onset
-- so the unresolved placement of the scale factor cannot move a bit. No field
-- is a band label, a threshold verdict, a region or a material.
--
-- All eighteen graded values were swept against every number the digest prints
-- and against every number handed to a learner in a prompt, at each field's own
-- shipped tolerance: 0 collisions, and 0 pairwise.
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug)
values ('corrosion', 'Corrosion & Integrity', 'facilities', 47, 'coming_soon', null)
on conflict (slug) do nothing;

insert into public.academy_capstones
    (app_slug, tier, cert_tier, dataset, title, prompt, fields)
values
(
  'corrosion', 'beginner', 'associate',
  'OBIGBO, a wet gas gathering line read from its composition to its corrosion inhibitor programme',
  'What is in the stream, how fast it moves, and what the programme delivers',
  'OBIGBO, a wet gas gathering line into the Obigbo manifold. Every condition here is stated in the engine''s own units, so nothing is converted through the studio. The line runs at 64.8 degC and a total pressure of 137.42 bar absolute. The gas carries a CO2 mole fraction of 0.0237 and an H2S mole fraction of 0.00093, and the in-situ pH is 4.62. The liquid moves at 3.4442 m/s in a line of 0.20272 m inside diameter, with a density of 860.19 kg/m3 and a viscosity of 0.00114 Pa s, and the line is water wet at a water cut of 1. The corrosion inhibitor is 87 percent efficient on its datasheet and is available 91.4 percent of the time. Report six values: the CO2 partial pressure; the H2S partial pressure in psia, converted by the bar to psia factor the engine exports; the H2S to CO2 mole ratio; this module''s Reynolds number, bearing in mind that the Pipeline & Line Sizing course computes its own and the two will not agree; the effective corrosion inhibition; and the metal loss as a ratio against what the datasheet efficiency alone would give. The Reynolds number to four decimals. The partial pressures in bar and psia, the inhibition in percent and both ratios to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','obigbo_co2_partial_pressure_bar', 'label','The CO2 partial pressure, the total pressure times the mole fraction', 'unit','bar', 'expected',3.2568539999999997, 'tol',5e-07),
    jsonb_build_object('key','obigbo_h2s_partial_pressure_psia', 'label','The H2S partial pressure, converted by the engine''s bar to psia factor', 'unit','psia', 'expected',1.8535909939965283, 'tol',5e-07),
    jsonb_build_object('key','obigbo_h2s_to_co2_mole_ratio', 'label','The H2S to CO2 mole ratio', 'unit','ratio', 'expected',0.039240506329113925, 'tol',5e-07),
    jsonb_build_object('key','obigbo_reynolds_number', 'label','This module''s Reynolds number, density times velocity times diameter over viscosity', 'unit','dimensionless', 'expected',526834.8528092633, 'tol',5e-05),
    jsonb_build_object('key','obigbo_effective_inhibition_pct', 'label','The effective corrosion inhibition the programme delivers', 'unit','percent', 'expected',79.518, 'tol',5e-07),
    jsonb_build_object('key','obigbo_metal_loss_ratio_vs_datasheet', 'label','The metal loss against what the datasheet efficiency alone would give', 'unit','ratio', 'expected',1.5755384615384613, 'tol',5e-07)
  )
),
(
  'corrosion', 'intermediate', 'professional',
  'NEMBE CREEK, an oil line on a surveyed rate, read through its corrosion inhibitor programme to its allowance',
  'The time average that eats the wall',
  'NEMBE CREEK, an oil line whose wall-loss rate came off a two-year ultrasonic survey. The survey gives an uninhibited rate of 1.9826 mm/yr. The line carries a corrosion allowance of 3.048 mm, of which 0.6731 mm is already consumed, against a design life of 18 years. The corrosion inhibitor is 93 percent efficient on its datasheet and is available 88.5 percent of the time. The engine''s own chain runs at 68.4 degC, 44.83 bar absolute, a CO2 mole fraction of 0.0192, an in-situ pH of 4.71, 2.1341 m/s and a 0.10318 m inside diameter, water wet, and none of those conditions moves any value asked for below. Report six values: the fraction of the metal loss the programme leaves; the corrosion inhibitor shortfall against the datasheet efficiency; the inhibited rate on the surveyed line; the remaining life at that rate; the allowance the design life demands at that rate; and the years of life the availability costs against the same corrosion inhibitor at full availability. The fraction as a plain number, the shortfall in percentage points, the rate in mm/yr, the allowance in mm and both lives in years, all to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','nembe_retained_metal_loss_fraction', 'label','The fraction of the metal loss the programme leaves', 'unit','fraction', 'expected',0.17694999999999994, 'tol',5e-07),
    jsonb_build_object('key','nembe_inhibitor_shortfall_pp', 'label','The corrosion inhibitor shortfall against the datasheet efficiency', 'unit','percentage points', 'expected',10.694999999999993, 'tol',5e-07),
    jsonb_build_object('key','nembe_inhibited_rate_mmyr', 'label','The inhibited rate on the surveyed line', 'unit','mm/yr', 'expected',0.35082106999999985, 'tol',5e-07),
    jsonb_build_object('key','nembe_remaining_life_yr', 'label','The remaining life at that inhibited rate', 'unit','yr', 'expected',6.769547792554197, 'tol',1e-06),
    jsonb_build_object('key','nembe_required_allowance_mm', 'label','The allowance the design life demands at that rate, which ignores what has gone', 'unit','mm', 'expected',6.314779259999997, 'tol',5e-07),
    jsonb_build_object('key','nembe_life_lost_to_availability_yr', 'label','The years of life the availability costs against full availability', 'unit','yr', 'expected',10.342901948766738, 'tol',1e-06)
  )
),
(
  'corrosion', 'advanced', 'expert',
  'SOKU, a gas line with its film stripped, worked back from its design life',
  'Inversion against the engine''s own verdict',
  'SOKU, a gas line where the wall shear has already stripped the corrosion inhibitor film, so the datasheet efficiency is not what the line sees. The operator''s inspection record gives an uninhibited rate of 2.1082 mm/yr. The line carries a corrosion allowance of 4.7625 mm, of which 1.3607 mm is already consumed, against a design life of 24 years. The corrosion inhibitor is 96 percent efficient on its datasheet and is available 82.3 percent of the time, and the target effective protection is 88 percent. The engine''s own chain runs at 74.9 degC, 88.61 bar absolute, a CO2 mole fraction of 0.0154, an in-situ pH of 4.83, 4.5739 m/s and a 0.15613 m inside diameter, water wet, and none of those conditions moves any value asked for below. Report six values: the largest rate at which the remaining allowance still meets the design life; the availability at which the effective protection first reaches the target, at the datasheet efficiency; the availability at which the programme, with its credit kept, brings the surveyed rate low enough to meet the design life; the total corrosion allowance that meets the design life at that credited rate, with the consumed depth unchanged; the remaining life at the uninhibited rate the stripped film leaves; and how many times longer the life at the credited rate is than that stripped life. Rates in mm/yr, availabilities in percent, the allowance in mm, the life in years and the ratio as a plain number, all to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','soku_tolerable_rate_mmyr', 'label','The largest rate at which the remaining allowance still meets the design life', 'unit','mm/yr', 'expected',0.14174166666666665, 'tol',5e-07),
    jsonb_build_object('key','soku_required_availability_pct', 'label','The availability at which the effective protection first reaches the target', 'unit','percent', 'expected',91.66666666666664, 'tol',5e-07),
    jsonb_build_object('key','soku_availability_for_design_life_pct', 'label','The availability at which the credited rate meets the design life', 'unit','percent', 'expected',97.16317698615987, 'tol',5e-07),
    jsonb_build_object('key','soku_allowance_to_reinstate_mm', 'label','The total allowance that reinstates the design life, consumed depth unchanged', 'unit','mm', 'expected',11.981980256000003, 'tol',5e-07),
    jsonb_build_object('key','soku_stripped_film_life_yr', 'label','The remaining life at the uninhibited rate the stripped film leaves', 'unit','yr', 'expected',1.6136040223887678, 'tol',1e-06),
    jsonb_build_object('key','soku_film_credit_life_ratio', 'label','How many times longer the life at the credited rate is than the stripped life', 'unit','ratio', 'expected',4.76371951219512, 'tol',5e-07)
  )
)
on conflict (app_slug, tier) do nothing;
